      const hasLive=(runtime?.getRuns(runtimeScope(state))||[]).length;
      const stream=runtime?(messages.length?'<details class="runtime-saved-notes" data-runtime-detail="saved-notes"><summary>本地便笺与示例 · '+messages.length+' 条</summary>'+savedStream+'</details>':'')+runtimeStream(state)+(!messages.length&&!hasLive?empty('从一个具体要求开始','选择伙伴，说明你的目标；执行记录与回复会出现在这里。'):''):savedStream;
      const mentions=(peer?[peer.id]:p.members).slice(0,7).map(id=>'<button class="mention-chip cursor-interaction" type="button" data-action="mention" data-id="'+id+'">@'+esc(name(id))+'</button>').join('');
      const legacyComposer=`<form class="composer" data-form="message"><label class="composer-label" for="message-text">${peer?'给 '+esc(peer.name)+' 的工作便笺':'补充你的意见'}</label><div class="mention-row">${mentions}</div><textarea class="composer-input" id="message-text" name="text" rows="3" maxlength="2000" placeholder="方向、参考资料，或需要调整的地方…" required>${esc(draft)}</textarea><div class="composer-footer"><span class="small muted">本地保存 · 执行器未接入</span><button class="button-primary cursor-interaction" type="submit">保存便笺 ↑</button></div></form>`;
      const composer=runtime?liveComposer(state,draft,ui):legacyComposer;
      if(peer)return intro(peer.name+'的工位',peer.title,p?button('返回项目','select-project',p.id):button('返回团队','navigate-team'))+`<div class="collaboration-layout"><section class="conversation-panel"><header class="conversation-header"><div class="participant-row">${avatar(peer.id)}<div><h2>独立工作会话</h2><p class="small muted">${esc(peer.summary)}</p></div></div>${badge('独立工位')}</header><div class="conversation-stream">${stream}</div>${composer}</section><aside class="inspector"><section class="inspector-section"><img class="member-profile-portrait" src="${esc(peer.portrait)}" alt="${esc(peer.name)}完整人物图"><h2>${esc(peer.name)}</h2><p>${esc(peer.title)}</p>${button('查看完整岗位','open-employee',peer.id)}</section><section class="inspector-section">${header('参与任务','本地登记的制作与复核任务')}${state.tasks.filter(t=>t.ownerId===peer.id||t.reviewerId===peer.id).map(t=>taskSummary(t,state,'open-task')).join('')||'<p class="small muted">还没有分配任务。</p>'}</section></aside></div>`;
      const list=tasks(state,p.id),t=list.find(t=>t.id===state.selectedTaskId)||list.find(t=>t.ownerId==='R04')||list[0],tab=p.kind==='game'&&state.projectTab==='production'?'overview':state.projectTab||'production';
      const key=visuals[state.selectedShot]?state.selectedShot:'cover';
      const assets=state.artifacts.filter(a=>a.projectId===p.id),liveAssets=runtime?.artifacts({projectId:p.id})||[];
      const tabs=[...(p.kind!=='game'?[['production','自动协作']]:[]),['media','影像制作'],['overview','概览'],['storyboard','分镜'],['assets','素材'],['tasks','任务'],['versions','版本']];
      if(tab==='media')return intro(p.title,'影像制作 · 生成进展与作品预览',selectProject(state))+'<nav class="project-tabs" aria-label="项目工作区">'+tabs.map(([id,label])=>'<button type="button" class="tab-button'+(id===tab?' is-active':'')+'" data-action="project-tab" data-id="'+id+'" aria-pressed="'+(id===tab)+'">'+label+'</button>').join('')+'</nav>'+(mediaViews?mediaViews.workspace(p,productionUI.getMediaUI?.(p.id)||{},mediaSources(state)):empty('影像制作模块未加载','请刷新工作台。'));
      let content='';
      if(tab==='production')content=productionViews?productionViews.workspace(p,productionUI):'<section class="project-stage"><h2>自动协作</h2><p>自动协作模块未加载，请刷新工作台。</p></section>';
      else if(tab==='assets')content='<div class="assets-gallery">'+assets.map(a=>deliveryCard(a,state)).join('')+'</div>'+(assets.length?'':empty('还没有共享素材','把项目资料登记为成果，就能在这里找到。',button('登记成果','new-artifact',p.id)));
      else if(tab==='tasks')content='<section class="project-stage">'+header('任务与交接',list.length+' 项本地任务',button('＋ 新建任务','new-task',p.id))+list.map(item=>taskSummary(item,state)).join('')+(t?'<div class="profile-section">'+flow(t)+button('查看与登记进展','open-task',t.id)+'</div>':'')+'</section>';
      else if(tab==='versions')content='<section class="project-stage">'+header('已登记版本','每份成果的正文、来源与审阅记录可回看。')+assets.map(a=>'<button type="button" class="artifact-mini cursor-interaction" data-action="review-asset" data-id="'+esc(a.id)+'"><span class="pill">'+esc(a.version)+'</span><span><strong>'+esc(a.title)+'</strong><small>'+esc(dateLabel(a.createdAt))+' · '+(a.source==='example'?'示例资料':'手动登记')+'</small></span><span>↗</span></button>').join('')+(assets.length?'':empty('尚未登记版本','保存共享成果后，这里会出现对应版本。'))+'</section>';
