      return intro(p.title,kinds[p.kind]+(p.isDemo?' · 示例项目':' · 本地项目'),selectProject(state))+`<div class="project-review-layout"><div class="project-main"><nav class="project-tabs" aria-label="项目工作区">${tabs.map(([id,label])=>'<button type="button" class="tab-button cursor-interaction'+(id===tab?' is-active':'')+'" data-action="project-tab" data-id="'+id+'" aria-pressed="'+(id===tab)+'">'+label+'</button>').join('')}</nav>${tab==='production'?'':runtimeArtifacts({projectId:p.id},true)}${content}</div><aside class="project-discussion"><div class="section-head"><div><h2>围绕作品协作</h2><p class="muted">对话 · 制作 · 交接</p></div>${badge(p.members.length+' 位伙伴')}</div>${p.isDemo?'<p class="small muted">下方“示例对话”是预设内容；新请求会真实执行。</p>':''}<div class="conversation-stream">${stream}</div><section class="profile-section">${header('相关成果','',button('全部 →','navigate-artifacts','','button-quiet'))}${liveAssets.slice(-2).reverse().map(a=>button('▤ '+esc(a.title),'runtime-artifact',a.id,'artifact-mini')).join('')}${assets.slice(0,2).map(a=>'<button type="button" class="artifact-mini" data-action="review-asset" data-id="'+esc(a.id)+'"><span>▤</span><span><strong>'+esc(a.title)+'</strong><small>'+esc(a.version)+' · '+(a.source==='example'?'示例资料':'本地登记')+'</small></span><span>↗</span></button>').join('')||(liveAssets.length?'':'<p class="small muted">暂无登记成果</p>')}</section><section class="profile-section">${header('协作流转',t?esc(t.title):'')}${flow(t)}${t?button('查看关联任务 →','open-task',t.id,'button-quiet'):''}</section>${composer}</aside></div>`;
